export function splitAtMidnight({ start, stop, ...rest }) {
  const mid = new Date(start);
  mid.setUTCHours(24, 0, 0, 0);
  if (new Date(stop) <= mid) return [{ start, stop, ...rest }];
  return [{ start, stop: mid.toISOString(), ...rest },
          ...splitAtMidnight({ start: mid.toISOString(), stop, ...rest })];
}

