// Hours are grouped by project because retainer clients pay against a per-project budget.
export function byProject(entries) {
  const totals = new Map();
  for (const e of entries) {
    const ms = new Date(e.stop) - new Date(e.start);
    totals.set(e.project, (totals.get(e.project) ?? 0) + ms);
  }
  return totals;
}
